def AmpBoundOfContDiffStatement : Prop :=
  ∀ (n : ℕ) (K : Set (ℝ × ℝ)) (A : ℝ × ℝ → ℂ), IsCompact K → ContDiff ℝ n A → tsupport A ⊆ K →
    ∃ M : ℝ, AmpBound n K A M

def DddEqIteratedStatement : Prop :=
  ∀ (Ψ : ℝ × ℝ → ℝ) (k : ℝ × ℝ), ContDiffAt ℝ 3 Ψ k →
    ∀ u v w, ddd Ψ k u v w = iteratedFDeriv ℝ 3 Ψ k ![u, v, w]

def CubicCoeffsEqStatement : Prop :=
  ∀ φ : ℝ × ℝ → ℝ, ContDiffAt ℝ 3 φ 0 →
    ∀ κ : ℝ × ℝ, cubicForm (cubicCoeffs φ) κ = iteratedFDeriv ℝ 3 φ 0 ![κ, κ, κ] / 6

def FamilyCkOfUncurryStatement : Prop :=
  ∀ (E : Type) [NormedAddCommGroup E] [NormedSpace ℝ E] (n : ℕ) (Ψ : E → ℝ × ℝ → ℝ),
    ContDiff ℝ n (Function.uncurry Ψ) → ∀ S : Set E, FamilyCk n (fun σ : S => Ψ σ)

def LatticeLaplacianLimitStatement : Prop :=
  Tendsto (fun n : ℕ => (((n : ℝ) ^ ((2 : ℝ) / 3) : ℝ) : ℂ) * (-1 : ℂ) ^ n * latticeKernel n ((n : ℤ), (n : ℤ)))
    atTop (𝓝 (d4ClosedConstant (-1 / 48) : ℂ))

def LatticeKernel1CubeRootStatement : Prop :=
  ∀ t ξ : ℝ, 0 < t →
    ‖latticeKernel1 t ξ‖ ≤ 8 * (1 + Real.sqrt 7) / 3 * t ^ (-(1 : ℝ) / 3)

def LatticeLaplacianCubeRootStatement : Prop :=
  ∀ (t : ℝ) (x : ℤ × ℤ), 0 < t →
    ‖latticeKernel t x‖ ≤ (8 * (1 + Real.sqrt 7) / 3) ^ 2 * t ^ (-(2 : ℝ) / 3)

def HypercubicCubeRootStatement : Prop :=
  ∀ (d : ℕ) (t : ℝ) (x : Fin d → ℤ), 0 < t →
    ‖hypercubicKernel d t x‖ ≤ (8 * (1 + Real.sqrt 7) / 3) ^ d * t ^ (-(d : ℝ) / 3)

def LatticeKernel1LightConeStatement : Prop :=
  ∀ (t η : ℝ) (n : ℤ), 0 ≤ η →
    ‖latticeKernel1 t (n : ℝ)‖ ≤ 2 * Real.pi * Real.exp (|t| * Real.sinh η - |(n : ℝ)| * η)

def KusminLandauStatement : Prop :=
  ∀ (c : ℕ → ℝ) (N : ℕ) (k : ℤ) (lam : ℝ), 0 < lam → lam ≤ 1 / 2 → DiffsMonotoneIn c N k lam →
    ‖expSum c N‖ ≤ Real.cos (Real.pi * lam / 2) / Real.sin (Real.pi * lam / 2)

def KusminLandauTwoOverPiStatement : Prop :=
  ∀ (c : ℕ → ℝ) (N : ℕ) (k : ℤ) (lam : ℝ), 0 < lam → lam ≤ 1 / 2 → DiffsMonotoneIn c N k lam →
    ‖expSum c N‖ ≤ 2 / (Real.pi * lam)

def RingCosetSumStatement : Prop :=
  ∀ (N : ℕ) (t : ℝ) (r : ℤ), 0 < N →
    HasSum (fun m : ℤ => lineKernel t (r + m * (N : ℤ))) (ringKernel N t r)

def HadamardKernelBoundStatement : Prop :=
  ∀ (t : ℕ) (x : ℤ), 1 ≤ t →
    ‖hadamardKernel t x‖ ≤ 7 * (t : ℝ) ^ (-(1 : ℝ) / 2) + 12 * (t : ℝ) ^ (-(1 : ℝ) / 3)

def StationaryLeadingStatement : Prop :=
  ∀ (g g₁ g₂ g₃ : ℝ → ℂ) (lam : ℝ), SplAmplitude g g₁ g₂ g₃ → 0 < lam →
    ∃ τ : ℝ, 0 ≤ τ ∧ ‖splRemainder g lam‖ ≤ ‖splKernel τ‖ * (∫ t, ‖g₃ t‖) * lam ^ (-(3 : ℝ) / 2)

def StationaryLeadingSevenEighthsStatement : Prop :=
  ∀ (g g₁ g₂ g₃ : ℝ → ℂ) (lam : ℝ), SplAmplitude g g₁ g₂ g₃ → 0 < lam →
    ‖splRemainder g lam‖ ≤ (7 / 8 : ℝ) * (∫ t, ‖g₃ t‖) * lam ^ (-(3 : ℝ) / 2)

def TriClassificationStatement : Prop :=
  ∀ α : ℝ, α ≠ 0 → ∀ k : ℝ × ℝ,
    FoldOrNondeg (triPhase α) k ∨ IsA3Point (triPhase α) k ∨ IsA5Point (triPhase α) k
